function calibrate(
  cv: Candidate,
  selected: Measured,
  train: Example[],
  test: Example[],
  p: Parameters,
) {
  const values = cv.values;
  const n = train.length;
  const m = test.length;
  const probabilities = selected.testValues.map((value) => probability(value, A, B));
function main() {
  const { train, test, multiTrain, multiTest, params: p } = read();
  const points = train.map((row) => row.point);
  const labels = train.map((row) => row.label);
  const matrices = p.kernels.map((kernel) => kernels.matrix(kernel, points));
  const cv = crossValidate(train, p, matrices);
  const finals = p.kernels.map((kernel) =>
    measure(
      smo.train(points, labels, matrices[kernel.index], cv.best[kernel.index].C, kernel, p),
      test,
    ),
  );
  const selected = finals[cv.selected.kernel.index];
  const blocks = [crossValidationLines(cv, train.length, p)];
  for (const result of finals) blocks.push(finalModelLines(result, train, test, p));
  blocks.push(...selectedAnalyses(selected, train, test, p));
  const calibration = calibrate(cv.selected, selected, train, test, p);
  blocks.push(calibration.lines, peg.lines, mcnemar(finals, peg.values, test));
  const modelLines: string[] = [];
  for (const block of blocks) {
    if (modelLines.length) modelLines.push('');
    modelLines.push(...block);
  }
  write('output/model.txt', modelLines);
  const grid = [
    [
      'kernel',
      'C',
      ...Array.from({ length: p.folds }, (_, i) => `fold${i + 1}`),
      'correct',
      'accuracy',
      'support_vectors',
      'passes',
      'steps',
    ].join(','),
  ];
  for (const e of cv.combinations) {
    grid.push(
      [
        e.kernel.name,
        fixed(e.C, 4),
        ...e.folds.map((f) => f.correct),
        e.correct,
        ratio(e.correct, train.length),
        e.support,
        e.passes,
        e.steps,
      ].join(','),
    );
  }
  write('output/cv_grid.csv', grid);
  const predictions = [
    [
      'id',
      'label',
      ...p.kernels.map((kernel) => kernel.name),
      'pegasos',
      'predicted',
      'probability',
    ].join(','),
  ];
  test.forEach((row, i) =>
    predictions.push(
      [
        row.id,
        row.label,
        ...finals.map((result) => fixed(result.testValues[i], 4)),
        fixed(peg.values[i], 4),
        sign(selected.testValues[i]),
        fixed(calibration.probabilities[i], 4),
      ].join(','),
    ),
  );
  write('output/predictions.csv', predictions);
